-- Adds Amana to the equipment catalog with real, sourced OEM extended
-- performance data (not AHRI single-point figures, not estimated) - see
-- EQUIPMENT-CATALOG-INVESTIGATION.md for the investigation that preceded
-- this, and the "Preferred Manufacturer" feature this unblocks.
--
-- Source: Amana SS-ASZ16 Expanded Cooling/Heating Data,
-- https://documents.alpinehomeair.com/product/Amana%20ASZ16%20Spec%20Sheets.pdf
-- (confirmed current 16-SEER split-system heat pump line on amana-hac.com
-- as of Aug 2026). Downloaded and parsed programmatically (PyMuPDF text
-- extraction + a structural parser matching this document's own repeating
-- outdoor-temp x entering-wetbulb grid), then spot-checked against the
-- raw extracted text before insertion - same standard as every other row
-- in this table.
--
-- 4 models across the ASZ16 line's full tonnage range (2/3/4/5-ton),
-- 254 real performance points (both entering-IDB conditions the document
-- publishes - 70F and 80F - kept rather than picked down to one, for
-- better interpolation coverage): 2-ton (ASZ160241K), 3-ton
-- (ASZ160361K), 4-ton (ASZ160481K, single-stage each), and 5-ton
-- (ASZ160601K, two-stage - High Stage curve used as the representative
-- data, same convention as the existing Carrier 24ACB7 row).
--
-- Honest data-quality note, disclosed per-row in source_document too:
-- this document's own "Expanded Cooling/Heating Data" tables are
-- published at a specific test airflow (710/1050/1400/1750 CFM
-- respectively) that runs somewhat below the AHRI-certified rating-point
-- airflow (880/1150/... CFM) shown for a different, newer cased-coil
-- combination elsewhere in the same document - the expanded tables were
-- never republished for that newer combination. This is real
-- manufacturer-published data for a real, still-valid coil pairing, not
-- fabricated - just not the identical airflow as the single AHRI
-- headline number for the newest coil option. Same category of
-- documented caveat the existing Carrier 24VNA660-30 row already carries
-- ("Maximum-demand curve only...").
--
-- NOT sourced this session (see EQUIPMENT-CATALOG-INVESTIGATION.md): the
-- other ~10 "top manufacturers" the Preferred Manufacturer dropdown will
-- eventually support (Trane, Lennox, Rheem, Ruud, American Standard,
-- York, Bryant, Daikin, Mitsubishi, etc.) - real OEM extended performance
-- data for each needs the same sourcing/parsing/verification treatment
-- this migration went through, not a batch fabrication. The dropdown and
-- ranking logic are built generically (DISTINCT manufacturer from this
-- table) so each drops in cleanly via a future migration exactly like
-- this one, no code changes required.

with catalog_ids as (
  insert into public.equipment_catalog
    (manufacturer, model_number, equipment_type, stage_type, nominal_cooling_capacity_btu, nominal_heating_capacity_btu, rated_cfm, source_document)
  values
    ('Amana', 'ASZ160241K', 'heat_pump', 'single', 24000, 23000, 710, 'Amana SS-ASZ16 Expanded Cooling/Heating Data (16 SEER split-system heat pump line, confirmed current on amana-hac.com), https://documents.alpinehomeair.com/product/Amana%20ASZ16%20Spec%20Sheets.pdf, p.4-5 (Expanded Cooling Data, 70F and 80F entering IDB tables, 710 CFM row), p.14 (Expanded Heating Data). Note: the 710 CFM shown in this document''s own Expanded Data tables is the manufacturer''s published test airflow for this specific coil pairing and runs below the AHRI-certified rating-point airflow shown elsewhere in the same document for a different (newer/cased) coil combination for this outdoor unit - same category of documented airflow-selection caveat as the existing Carrier/Goodman rows.'),
    ('Amana', 'ASZ160361K', 'heat_pump', 'single', 34600, 34400, 1050, 'Amana SS-ASZ16 Expanded Cooling/Heating Data (16 SEER split-system heat pump line, confirmed current on amana-hac.com), https://documents.alpinehomeair.com/product/Amana%20ASZ16%20Spec%20Sheets.pdf, p.6-7 (Expanded Cooling Data, 70F and 80F entering IDB tables, 1050 CFM row), p.14 (Expanded Heating Data). Note: the 1050 CFM shown in this document''s own Expanded Data tables is the manufacturer''s published test airflow for this specific coil pairing and runs below the AHRI-certified rating-point airflow shown elsewhere in the same document for a different (newer/cased) coil combination for this outdoor unit - same category of documented airflow-selection caveat as the existing Carrier/Goodman rows.'),
    ('Amana', 'ASZ160481K', 'heat_pump', 'single', 47000, 46000, 1400, 'Amana SS-ASZ16 Expanded Cooling/Heating Data (16 SEER split-system heat pump line, confirmed current on amana-hac.com), https://documents.alpinehomeair.com/product/Amana%20ASZ16%20Spec%20Sheets.pdf, p.8-9 (Expanded Cooling Data, 70F and 80F entering IDB tables, 1400 CFM row), p.14 (Expanded Heating Data). Note: the 1400 CFM shown in this document''s own Expanded Data tables is the manufacturer''s published test airflow for this specific coil pairing and runs below the AHRI-certified rating-point airflow shown elsewhere in the same document for a different (newer/cased) coil combination for this outdoor unit - same category of documented airflow-selection caveat as the existing Carrier/Goodman rows.'),
    ('Amana', 'ASZ160601K', 'heat_pump', 'two_stage', 57000, 56500, 1750, 'Amana SS-ASZ16 Expanded Cooling/Heating Data (16 SEER split-system heat pump line, confirmed current on amana-hac.com), https://documents.alpinehomeair.com/product/Amana%20ASZ16%20Spec%20Sheets.pdf, p.12-13 (High Stage) (Expanded Cooling Data, 70F and 80F entering IDB tables, 1750 CFM row), p.15 (High Stage) (Expanded Heating Data). Note: the 1750 CFM shown in this document''s own Expanded Data tables is the manufacturer''s published test airflow for this specific coil pairing and runs below the AHRI-certified rating-point airflow shown elsewhere in the same document for a different (newer/cased) coil combination for this outdoor unit - same category of documented airflow-selection caveat as the existing Carrier/Goodman rows.')
  returning id, model_number
)
insert into public.equipment_performance_points
  (equipment_id, mode, outdoor_temp_f, indoor_entering_temp_f, indoor_entering_wetbulb_f, sensible_capacity_btu, total_capacity_btu, input_power_kw)
